package jp.haruya.novelstudio;

import android.content.Context;
import android.util.AtomicFile;
import org.json.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;

/** Production store/protocol checks. Provider network and Android Keystore are never used. */
public class NarrationChecks {
    static int count;
    static void check(boolean b,String m){if(!b)throw new AssertionError(m);count++;}
    interface Op{void run()throws Exception;}
    static void reject(Op o,String m)throws Exception {try{o.run();throw new AssertionError("accepted: "+m);}catch(IOException expected){count++;}}
    static JSONObject o(Object...args){return NarrationStore.obj(args);}
    static final String BODY="玲司は扉を見た。\n「やっと見つけた」\n（これなら間に合う）\n凛が笑った。🌙\n";
    static JSONObject character(String id,String name,String role,String voice){return o("id",id,"name",name,"aliases","","role",role,"gender",voice.equals("Charon")?"male":"female","voice",voice,"deviceVoice","","rate",1.0,"pitch",1.0,"volume",1.0);}
    static JSONObject result(String body)throws Exception {JSONArray spans=NarrationStore.split(body),out=new JSONArray();for(int i=0;i<spans.length();i++){JSONObject s=spans.getJSONObject(i);String text=s.getString("text");if(text.trim().isEmpty())continue;out.put(o("id",s.getString("id"),"speaker",text.startsWith("「")||text.startsWith("（")?"reiji":"narrator","kind",text.startsWith("「")?"dialogue":text.startsWith("（")?"thought":"narration","emotion",text.startsWith("（")?"whisper":"neutral","rate",1,"pitch",1,"volume",text.startsWith("（")?.6:1,"style","","pauseMs",100));}return o("characters",new JSONArray().put(character("reiji","三枝玲司","main","Charon")).put(character("rin","凛","sub","Kore")),"segments",out);}
    static JSONObject prepare(NarrationStore s,String cid,String body)throws Exception{return s.prepare("book_test",cid,body,"第1話","test-model","",new JSONArray(),true);}
    static void complete(NarrationStore s,JSONObject req,JSONObject output)throws Exception {s.accept(o("requestId",req.getString("requestId"),"phase","complete","text",output.toString()));}
    public static void main(String[] args)throws Exception {
        String[] samples={BODY,"\n\n短い\r\n本文。　「発言」「続き」（心の声）",new String(new char[639]).replace('\0','字')+"🌙末尾","x🌙"+new String(new char[1000]).replace('\0','文')};
        for(String text:samples){JSONArray spans=NarrationStore.split(text);StringBuilder restored=new StringBuilder();int at=0;for(int i=0;i<spans.length();i++){JSONObject seg=spans.getJSONObject(i);check(seg.getInt("start")==at,"contiguous source span");String part=seg.getString("text");check(!Character.isHighSurrogate(part.charAt(part.length()-1)),"surrogate intact");at=seg.getInt("end");restored.append(part);}check(text.equals(restored.toString()),"source copied exactly");}
        reject(()->NarrationStore.split("   "),"empty source");check(NarrationStore.split(new String(new char[60001]).replace('\0','字')).length()>0,"long source accepted");check(NarrationStore.split(new String(new char[601]).replace('\0','\n')+"a").length()>600,"600 segment limit removed");
        Context context=new Context();NarrationStore s=new NarrationStore(context);JSONObject request=prepare(s,"chapter_one",BODY);JSONObject output=result(BODY);check(request.getString("instructions").contains("本文を改変せず"),"data-only annotation prompt");
        check(!s.accept(o("requestId",request.getString("requestId"),"phase","delta","delta","partial")),"deltas do not acknowledge incomplete JSON");complete(s,request,output);
        JSONObject view=s.view("book_test","chapter_one"),plan=s.plan("book_test","chapter_one",BODY);check(view.getJSONObject("pending").getString("phase").equals("complete"),"valid AI result committed");check(plan.getString("source").equals(BODY),"AI cannot rewrite source");check(plan.getJSONArray("cast").length()==4,"main/sub plus standard voices");
        JSONArray segs=plan.getJSONArray("segments");boolean thought=false;for(int i=0;i<segs.length();i++)if(segs.getJSONObject(i).optString("kind").equals("thought")){thought=true;check(segs.getJSONObject(i).optString("speaker").equals("reiji"),"inner voice owned by character");}check(thought,"inner thought present");
        JSONObject manual=NarrationStore.copy(NarrationStore.find(view.getJSONArray("cast"),"reiji"));manual.put("voice","Orus");manual.put("rate",.85);manual.put("aliases","玲司,博士");s.saveCharacter("book_test",manual);
        JSONObject req2=prepare(s,"chapter_two",BODY),res2=result(BODY);res2.getJSONArray("characters").getJSONObject(0).put("id","doctor").put("name","玲司");JSONArray a2=res2.getJSONArray("segments");for(int i=0;i<a2.length();i++)if("reiji".equals(a2.getJSONObject(i).optString("speaker")))a2.getJSONObject(i).put("speaker","doctor");complete(s,req2,res2);
        view=s.view("book_test","chapter_two");check(view.getJSONArray("cast").length()==4,"aliases prevent duplicate cast");JSONObject kept=NarrationStore.find(view.getJSONArray("cast"),"reiji");check(kept.optString("voice").equals("Orus")&&kept.optBoolean("locked")&&kept.optDouble("rate")==.85,"manual voice persists across chapters");
        String valid=view.getJSONObject("plan").toString();JSONObject broken=result(BODY);broken.getJSONArray("segments").remove(0);complete(s,prepare(s,"chapter_two",BODY),broken);check(s.view("book_test","chapter_two").getJSONObject("plan").toString().equals(valid),"missing segments preserve prior plan");
        broken=result(BODY);broken.getJSONArray("segments").getJSONObject(0).put("speaker","nonexistent");complete(s,prepare(s,"chapter_two",BODY),broken);check(s.view("book_test","chapter_two").getJSONArray("cast").length()==4,"unknown speaker rolls back cast too");
        broken=result(BODY);broken.getJSONArray("segments").getJSONObject(1).put("id","s0");complete(s,prepare(s,"chapter_two",BODY),broken);check(s.view("book_test","chapter_two").getJSONObject("pending").optString("phase").equals("paused"),"duplicate segment paused for recovery");
        broken=result(BODY);broken.getJSONArray("segments").getJSONObject(0).put("pitch",99);complete(s,prepare(s,"chapter_two",BODY),broken);check(s.view("book_test","chapter_two").getJSONObject("plan").toString().equals(valid),"invalid numeric annotation is atomic");
        reject(()->s.plan("book_test","chapter_one",BODY+"編集"),"stale source blocked");
        JSONObject corrected=NarrationStore.copy(s.plan("book_test","chapter_one",BODY).getJSONArray("segments").getJSONObject(1));corrected.put("speaker","rin");corrected.put("kind","thought");corrected.put("emotion","happy");s.saveSegment("book_test","chapter_one",corrected);check(s.plan("book_test","chapter_one",BODY).getJSONArray("segments").getJSONObject(1).optString("speaker").equals("rin"),"manual speaker correction");
        s.checkpoint(o("bookId","book_test","chapterId","chapter_one","hash",NarrationStore.hash(BODY),"index",2,"offset",1234));NarrationStore recreated=new NarrationStore(context);check(recreated.checkpoint().optInt("offset")==1234,"process restart restores audio offset");check(recreated.view("book_test","chapter_two").getJSONArray("cast").length()==4,"cast durable after recreation");
        JSONObject before=s.exportData();AtomicFile.failFinish=true;try{reject(()->s.checkpoint(o("index",999)),"silent AtomicFile failure detected");}finally{AtomicFile.failFinish=false;}check(before.toString().equals(s.exportData().toString()),"failed write does not advance in-memory checkpoint");
        JSONObject backup=s.exportData();NarrationStore other=new NarrationStore(new Context());other.importData(backup);check(other.plan("book_test","chapter_one",BODY).getJSONArray("segments").length()==segs.length(),"backup round trip");backup.getJSONObject("books").getJSONObject("book_test").getJSONObject("plans").getJSONObject("chapter_one").getJSONArray("segments").getJSONObject(0).put("text","改変");reject(()->other.importData(backup),"tampered source rejected");
        JSONObject speech=SpeechAudioClient.request(SpeechCatalog.DEFAULT_MODEL,"Kore","こんにちは。","穏やかに。");check(speech.optString("model").equals(SpeechCatalog.DEFAULT_MODEL),"current TTS model");check(speech.getJSONObject("response_format").optString("mime_type").equals("audio/wav"),"WAV explicitly requested");check(speech.getJSONArray("input").getJSONObject(0).getJSONArray("content").getJSONObject(0).getString("text").equals("こんにちは。"),"exact speech text");
        JSONObject response=o("steps",new JSONArray().put(o("type","model_output","content",new JSONArray().put(o("type","text","text","ignored")).put(o("type","audio","mime_type","audio/wav","data","YWJj")))));check(SpeechAudioClient.audioData(response).equals("YWJj"),"Interactions steps parsed");response.getJSONArray("steps").getJSONObject(0).getJSONArray("content").getJSONObject(1).put("mime_type","audio/l16");reject(()->SpeechAudioClient.audioData(response),"unexpected PCM rejected");reject(()->SpeechAudioClient.audioData(o("steps",new JSONArray())),"missing audio rejected");check(!SpeechAudioClient.wav(new byte[45]),"non-WAV rejected");
        JSONObject signaturePlan=s.plan("book_test","chapter_one",BODY);String signature=SpeechAudioClient.signature(signaturePlan,0);check(signature.equals(SpeechAudioClient.signature(NarrationStore.copy(signaturePlan),0)),"same voice settings permit exact offset resume");signaturePlan.put("engine","gemini");check(!signature.equals(SpeechAudioClient.signature(signaturePlan,0)),"engine change invalidates audio offset");
        SpeechAudioClient cancelled=new SpeechAudioClient(context);reject(()->cancelled.synthesize(SpeechCatalog.DEFAULT_MODEL,character("a","A","main","Charon"),o("text","未送信"),()->false),"cancelled queued synthesis never reaches credentials or HTTP");
        check(SpeechCatalog.voices().length()==30,"30 named voices");Set<String> names=new HashSet<>();for(int i=0;i<SpeechCatalog.voices().length();i++)names.add(SpeechCatalog.voices().getJSONObject(i).getString("id"));check(names.size()==30,"unique catalog");
        System.out.println("PASS "+count+" narration store/protocol assertions; no live TTS calls.");
    }
}
